// localStorage helpers for tracking practiced questions
const PRACTICED_KEY = "quiz_practiced_questions";
export function getPracticedIds(categoryId: string): number[] {
  try {
    const data = JSON.parse(localStorage.getItem(PRACTICED_KEY) || "{}");
    return data[categoryId] || [];
  } catch {
    return [];
  }
}
export function savePracticedIds(categoryId: string, ids: number[]): void {
  try {
    const data = JSON.parse(localStorage.getItem(PRACTICED_KEY) || "{}");
    const existing = new Set(data[categoryId] || []);
    ids.forEach((id) => existing.add(id));
    data[categoryId] = [...existing];
    localStorage.setItem(PRACTICED_KEY, JSON.stringify(data));
  } catch { }
}
export function resetPracticedIds(categoryId: string): void {
  try {
    const data = JSON.parse(localStorage.getItem(PRACTICED_KEY) || "{}");
    delete data[categoryId];
    localStorage.setItem(PRACTICED_KEY, JSON.stringify(data));
  } catch { }
}
export function getUnpracticedQuestions(category: Category): Question[] {
  const practiced = new Set(getPracticedIds(category.id));
  return category.questions.filter((q) => !practiced.has(q.id));
}
export function getTotalPracticed(categoryId: string): number {
  return getPracticedIds(categoryId).length;
}
